#define TWO_PI 6.28318530718
#define PI     3.14159265359
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy - 0.5;
    uv.x *= iResolution.x / iResolution.y;

    float r = length(uv);
    float theta = atan(uv.y, uv.x);
    // 将角度范围标准化到 [0, TWO_PI]
    if(theta < 0.0) theta += TWO_PI;

    float innerMask = step(0.31, r);
    float barCount = 20.0;  // 这将是实际的栏杆数量
    float width = 0.08;      // 调整宽度使栏杆更明显

    // 计算当前栏杆的索引 (0 到 barCount-1)
    float barIndex = floor(theta / TWO_PI * barCount);

    // 计算当前角度在当前栏杆区域内的相对位置
    float barPhase = fract(theta / TWO_PI * barCount);

    // 创建栏杆mask
    float fence = step(0.5 - width, barPhase) * step(barPhase, 0.5 + width);

    // 为每个栏杆设置延迟
    float delay = barIndex * 0.15; // 每个栏杆延迟0.2秒
    float t = sin((iTime - delay) * 2.0) * 0.25 + 0.5;

    // 在延迟时间之前保持在初始位置
    t = iTime < delay ? 0.0 : t;

    float barRadiusBase = 0.5;
    float barRadiusAnim = mix(0.35, 0.45, t);

    float finalBarRadius = barRadiusAnim;

    float barMask = smoothstep(finalBarRadius + 0.01, finalBarRadius, r);
    float combinedMask = barMask * fence * innerMask;

    vec3 blueColor = vec3(0.863,0.867,0.976);
    fragColor = vec4(blueColor * combinedMask, 1.);
}
